"use client";

/* eslint-disable @next/next/no-img-element -- QR code is a data: URL generated by Supabase Auth */
import { useRouter } from "next/navigation";
import { useEffect, useState, type FormEvent } from "react";
import { AuthShell } from "@/components/AuthShell";
import { createClient } from "@/lib/supabase/client";

type Enrolment = { factorId: string; qrCode: string; secret: string };

export default function MfaPage() {
  const router = useRouter();
  const [factorId, setFactorId] = useState<string | null>(null);
  const [enrolment, setEnrolment] = useState<Enrolment | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    const supabase = createClient();
    (async () => {
      const { data, error: listError } = await supabase.auth.mfa.listFactors();
      if (listError) {
        setError("Could not load authentication factors.");
        return;
      }
      const verified = data.totp.find((f) => f.status === "verified");
      if (verified) {
        setFactorId(verified.id);
        return;
      }
      // Remove abandoned, unverified enrolments before starting a fresh one.
      for (const factor of data.all.filter((f) => f.status === "unverified")) {
        await supabase.auth.mfa.unenroll({ factorId: factor.id });
      }
      const { data: enrolled, error: enrolError } = await supabase.auth.mfa.enroll({
        factorType: "totp",
        friendlyName: "Authenticator app",
      });
      if (enrolError || !enrolled) {
        setError("Could not start two-factor setup.");
        return;
      }
      setFactorId(enrolled.id);
      setEnrolment({ factorId: enrolled.id, qrCode: enrolled.totp.qr_code, secret: enrolled.totp.secret });
    })();
  }, []);

  async function onVerify(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!factorId) return;
    setBusy(true);
    setError(null);
    const code = String(new FormData(event.currentTarget).get("code") ?? "").trim();
    const supabase = createClient();
    const { error: verifyError } = await supabase.auth.mfa.challengeAndVerify({ factorId, code });
    if (verifyError) {
      setError("That code was not accepted. Try the current code from your app.");
      setBusy(false);
      return;
    }
    router.replace("/dashboard");
    router.refresh();
  }

  return (
    <AuthShell
      title="Two-factor authentication"
      asideTitle="An extra lock on your clinic's workspace."
      asideText="A code from your authenticator app keeps your account safe, even if your password is ever exposed."
    >
      {enrolment ? (
        <>
          <p>Scan this QR code with an authenticator app, then enter the 6-digit code.</p>
          <img src={enrolment.qrCode} alt="Authenticator QR code" width={180} height={180} className="auth-qr" />
          <details>
            <summary>Can&apos;t scan? Enter this key manually</summary>
            <code className="secret">{enrolment.secret}</code>
          </details>
        </>
      ) : (
        <p>Enter the 6-digit code from your authenticator app.</p>
      )}
      <form onSubmit={onVerify} className="form">
        <label>
          Code
          <input name="code" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code" required />
        </label>
        {error && <p role="alert" className="error">{error}</p>}
        <button type="submit" disabled={busy || !factorId}>{busy ? "Verifying…" : "Verify"}</button>
      </form>
    </AuthShell>
  );
}
